def md5_int(i):
    return int(hashlib.md5(str(i).encode()).hexdigest(), 16)

def myHash(msg: str) -> int:
    # padding
    msg += "y"
    if len(msg) % 8 != 0:
        msg += "x" * (8 - len(msg) % 8)

    IV = 67 
    # process in blocks.block size = 8
    for start in range(0, len(msg), 8):
        block = msg[start:start+8]
        total = IV
        for i, c in enumerate(block):
            total += (ord(c) ** (i+1)) + md5_int(i)
        total = (total * 6767) % (10**12)
        IV = total
    return IV # result of last block

import random, string

def random_input(length=7):
    return ''.join(random.choices(string.printable[:94], k=length))

def find_collision(max_tries=2000_000):
    seen = {}
    for _ in range(max_tries):
        msg = random_input()
        h = myHash(msg)
        if h in seen and seen[msg] if False else (h in seen and seen[h] != msg):
            return seen[h], msg, h
        seen[h] = msg
    return None

